mapper.select:
SELECT
    p.id,p.name,p.price,p.sales,p.stock,p.image,p.status,p.create_time,
    c.name AS category_name
FROM t_product p
         LEFT JOIN t_category c ON p.category_id = c.id



        AND c.id = #{dto.id}


        AND p.seller_id = #{dto.userId}


        AND p.name LIKE CONCAT('%',#{dto.name},'%')


        AND c.parent_id = #{dto.categoryId}


        AND p.price >= #{dto.minPrice}


        AND p.price <= #{dto.maxPrice}


        AND p.status = #{dto.status}

    AND p.deleted = 0


    ORDER BY ${dto.sortField} ${dto.sortOrder}
